layer.css:
[data-ryt="footer"] { color: var(--ryt-text); background-color: rgb(21, 22, 24); border-top: 1px solid var(--ryt-border); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-bg); background-image: linear-gradient(to right bottom, rgb(59, 61, 67), rgb(45, 47, 52)); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 8px; box-shadow: rgba(0, 0, 0, 0) 0px 0px 0px 0px, rgba(0, 0, 0, 0) 0px 0px 0px 0px, rgba(0, 0, 0, 0.1) 0px 10px 15px -3px, rgba(0, 0, 0, 0.1) 0px 4px 6px -4px; transition: 0.3s; padding-top: 24px; position: relative }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 30px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; position: relative }
[data-ryt="header"] { box-shadow: rgba(0, 0, 0, 0) 0px 0px 0px 0px, rgba(0, 0, 0, 0) 0px 0px 0px 0px, rgba(0, 0, 0, 0.1) 0px 4px 6px -1px, rgba(0, 0, 0, 0.1) 0px 2px 4px -2px }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: rgb(218, 219, 220); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(218, 219, 220); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="review"] { color: rgb(218, 219, 220); font-family: var(--ryt-font-body); font-size: 14px; font-weight: 400; font-style: italic; line-height: 1.429; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(218, 219, 220); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; padding-bottom: 6px; position: relative }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 700; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a::after { content: ""; display: block; position: absolute; height: 2px; color: var(--ryt-text); background-image: linear-gradient(90deg, rgb(71, 74, 81), rgb(57, 59, 65)); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 700; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text); bottom: -2px; left: 0px }
[data-ryt="nav"] a::after { content: ""; display: block; position: absolute; height: 2px; color: var(--ryt-text); background-color: rgb(60, 176, 67); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: width 0.3s; -webkit-text-fill-color: var(--ryt-text); bottom: 0px; left: 0px }
[data-ryt="nav"] a:hover { color: #3CB043 }
article[data-ryt="rec-card"]::before { content: ""; display: block; position: absolute; width: 100%; height: 3px; color: var(--ryt-text); background-image: linear-gradient(90deg, rgb(60, 176, 67), rgb(48, 141, 54)); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text); top: 0px; left: 0px }
article[data-ryt="rec-card"]:hover { transform: translateY(calc(-1 * 4px)); box-shadow: rgba(0, 0, 0, 0.15) 0px 10px 25px; box-shadow: rgba(0, 0, 0, 0.4) 0px 10px 25px }
